func NewParsingValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (ParsingValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing ParsingValue Attribute Value",
				"While creating a ParsingValue value, a missing attribute value was detected. "+
					"A ParsingValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("ParsingValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid ParsingValue Attribute Type",
				"While creating a ParsingValue value, an invalid attribute value was detected. "+
					"A ParsingValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("ParsingValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("ParsingValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra ParsingValue Attribute Value",
				"While creating a ParsingValue value, an extra attribute value was detected. "+
					"A ParsingValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra ParsingValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewParsingValueUnknown(), diags
	}

	candidateRowCountAttribute, ok := attributes["candidate_row_count"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`candidate_row_count is missing from object`)

		return NewParsingValueUnknown(), diags
	}

	candidateRowCountVal, ok := candidateRowCountAttribute.(basetypes.Int64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`candidate_row_count expected to be basetypes.Int64Value, was: %T`, candidateRowCountAttribute))
	}

	examplesAttribute, ok := attributes["examples"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`examples is missing from object`)

		return NewParsingValueUnknown(), diags
	}

	examplesVal, ok := examplesAttribute.(basetypes.ListValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`examples expected to be basetypes.ListValue, was: %T`, examplesAttribute))
	}

	parsedRowCountAttribute, ok := attributes["parsed_row_count"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`parsed_row_count is missing from object`)

		return NewParsingValueUnknown(), diags
	}

	parsedRowCountVal, ok := parsedRowCountAttribute.(basetypes.Int64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`parsed_row_count expected to be basetypes.Int64Value, was: %T`, parsedRowCountAttribute))
	}

	populatedRowCountAttribute, ok := attributes["populated_row_count"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`populated_row_count is missing from object`)

		return NewParsingValueUnknown(), diags
	}

	populatedRowCountVal, ok := populatedRowCountAttribute.(basetypes.Int64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`populated_row_count expected to be basetypes.Int64Value, was: %T`, populatedRowCountAttribute))
	}

	staleBeforeAttribute, ok := attributes["stale_before"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`stale_before is missing from object`)

		return NewParsingValueUnknown(), diags
	}

	staleBeforeVal, ok := staleBeforeAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`stale_before expected to be basetypes.StringValue, was: %T`, staleBeforeAttribute))
	}

	staleExamplesAttribute, ok := attributes["stale_examples"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`stale_examples is missing from object`)

		return NewParsingValueUnknown(), diags
	}

	staleExamplesVal, ok := staleExamplesAttribute.(basetypes.ListValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`stale_examples expected to be basetypes.ListValue, was: %T`, staleExamplesAttribute))
	}

	staleRowCountAttribute, ok := attributes["stale_row_count"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`stale_row_count is missing from object`)

		return NewParsingValueUnknown(), diags
	}

	staleRowCountVal, ok := staleRowCountAttribute.(basetypes.Int64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`stale_row_count expected to be basetypes.Int64Value, was: %T`, staleRowCountAttribute))
	}

	if diags.HasError() {
		return NewParsingValueUnknown(), diags
	}

	return ParsingValue{
		CandidateRowCount: candidateRowCountVal,
		Examples:          examplesVal,
		ParsedRowCount:    parsedRowCountVal,
		PopulatedRowCount: populatedRowCountVal,
		StaleBefore:       staleBeforeVal,
		StaleExamples:     staleExamplesVal,
		StaleRowCount:     staleRowCountVal,
		state:             attr.ValueStateKnown,
	}, diags
}

func NewParsingValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) ParsingValue {
	object, diags := NewParsingValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewParsingValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t ParsingType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewParsingValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewParsingValueUnknown(), nil
	}

	if in.IsNull() {
		return NewParsingValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewParsingValueMust(ParsingValue{}.AttributeTypes(ctx), attributes), nil
}

func (t ParsingType) ValueType(ctx context.Context) attr.Value {
	return ParsingValue{}
}

var _ basetypes.ObjectValuable = ParsingValue{}

type ParsingValue struct {
	CandidateRowCount basetypes.Int64Value  `tfsdk:"candidate_row_count"`
	Examples          basetypes.ListValue   `tfsdk:"examples"`
	ParsedRowCount    basetypes.Int64Value  `tfsdk:"parsed_row_count"`
	PopulatedRowCount basetypes.Int64Value  `tfsdk:"populated_row_count"`
	StaleBefore       basetypes.StringValue `tfsdk:"stale_before"`
	StaleExamples     basetypes.ListValue   `tfsdk:"stale_examples"`
	StaleRowCount     basetypes.Int64Value  `tfsdk:"stale_row_count"`
	state             attr.ValueState
}

func (v ParsingValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 7)

	var val tftypes.Value
	var err error

	attrTypes["candidate_row_count"] = basetypes.Int64Type{}.TerraformType(ctx)
	attrTypes["examples"] = basetypes.ListType{
		ElemType: types.StringType,
	}.TerraformType(ctx)
	attrTypes["parsed_row_count"] = basetypes.Int64Type{}.TerraformType(ctx)
	attrTypes["populated_row_count"] = basetypes.Int64Type{}.TerraformType(ctx)
	attrTypes["stale_before"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["stale_examples"] = basetypes.ListType{
		ElemType: types.StringType,
	}.TerraformType(ctx)
	attrTypes["stale_row_count"] = basetypes.Int64Type{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 7)

		val, err = v.CandidateRowCount.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["candidate_row_count"] = val

		val, err = v.Examples.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["examples"] = val

		val, err = v.ParsedRowCount.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["parsed_row_count"] = val

		val, err = v.PopulatedRowCount.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["populated_row_count"] = val

		val, err = v.StaleBefore.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["stale_before"] = val

		val, err = v.StaleExamples.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["stale_examples"] = val

		val, err = v.StaleRowCount.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["stale_row_count"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

func (v ParsingValue) IsNull() bool {
	return v.state == attr.ValueStateNull
}

func (v ParsingValue) IsUnknown() bool {
	return v.state == attr.ValueStateUnknown
}

func (v ParsingValue) String() string {
	return "ParsingValue"
}

func (v ParsingValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var examplesVal basetypes.ListValue
	switch {
	case v.Examples.IsUnknown():
		examplesVal = types.ListUnknown(types.StringType)
	case v.Examples.IsNull():
		examplesVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		examplesVal, d = types.ListValue(types.StringType, v.Examples.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"candidate_row_count": basetypes.Int64Type{},
			"examples": basetypes.ListType{
				ElemType: types.StringType,
			},
			"parsed_row_count":    basetypes.Int64Type{},
			"populated_row_count": basetypes.Int64Type{},
			"stale_before":        basetypes.StringType{},
			"stale_examples": basetypes.ListType{
				ElemType: types.StringType,
			},
			"stale_row_count": basetypes.Int64Type{},
		}), diags
	}

	var staleExamplesVal basetypes.ListValue
	switch {
	case v.StaleExamples.IsUnknown():
		staleExamplesVal = types.ListUnknown(types.StringType)
	case v.StaleExamples.IsNull():
		staleExamplesVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		staleExamplesVal, d = types.ListValue(types.StringType, v.StaleExamples.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"candidate_row_count": basetypes.Int64Type{},
			"examples": basetypes.ListType{
				ElemType: types.StringType,
			},
			"parsed_row_count":    basetypes.Int64Type{},
			"populated_row_count": basetypes.Int64Type{},
			"stale_before":        basetypes.StringType{},
			"stale_examples": basetypes.ListType{
				ElemType: types.StringType,
			},
			"stale_row_count": basetypes.Int64Type{},
		}), diags
	}

	attributeTypes := map[string]attr.Type{
		"candidate_row_count": basetypes.Int64Type{},
		"examples": basetypes.ListType{
			ElemType: types.StringType,
		},
		"parsed_row_count":    basetypes.Int64Type{},
		"populated_row_count": basetypes.Int64Type{},
		"stale_before":        basetypes.StringType{},
		"stale_examples": basetypes.ListType{
			ElemType: types.StringType,
		},
		"stale_row_count": basetypes.Int64Type{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"candidate_row_count": v.CandidateRowCount,
			"examples":            examplesVal,
			"parsed_row_count":    v.ParsedRowCount,
			"populated_row_count": v.PopulatedRowCount,
			"stale_before":        v.StaleBefore,
			"stale_examples":      staleExamplesVal,
			"stale_row_count":     v.StaleRowCount,
		})

	return objVal, diags
}

func (v ParsingValue) Equal(o attr.Value) bool {
	other, ok := o.(ParsingValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.CandidateRowCount.Equal(other.CandidateRowCount) {
		return false
	}

	if !v.Examples.Equal(other.Examples) {
		return false
	}

	if !v.ParsedRowCount.Equal(other.ParsedRowCount) {
		return false
	}

	if !v.PopulatedRowCount.Equal(other.PopulatedRowCount) {
		return false
	}

	if !v.StaleBefore.Equal(other.StaleBefore) {
		return false
	}

	if !v.StaleExamples.Equal(other.StaleExamples) {
		return false
	}

	if !v.StaleRowCount.Equal(other.StaleRowCount) {
		return false
	}

	return true
}

func (v ParsingValue) Type(ctx context.Context) attr.Type {
	return ParsingType{
		basetypes.ObjectType{
			AttrTypes: v.AttributeTypes(ctx),
		},
	}
}

